previewCss:
.darma-loader-darma-b14-wind-chimes { --accent: var(--loader-color, #cbd5e1); --accent-2: var(--loader-secondary-color, #a16207); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; display: flex; justify-content: space-evenly; padding-top: 12%; }
.darma-loader-darma-b14-wind-chimes::before { content: ''; position: absolute; top: 6%; left: 16%; width: 68%; height: 4%; border-radius: 999px; background: color-mix(in srgb, #000 30%, var(--accent-2)); }
.darma-loader-darma-b14-wind-chimes span { width: 10%; border-radius: 999px; transform-origin: top center; background: linear-gradient(90deg, color-mix(in srgb, #fff 62%, var(--accent)) 0 26%, var(--accent) 34% 76%, color-mix(in srgb, #000 26%, var(--accent)) 84%); animation: darma-loader-darma-b14-wind-chimes-chime calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b14-wind-chimes span:nth-child(1) { height: 76%; }
.darma-loader-darma-b14-wind-chimes span:nth-child(2) { height: 60%; animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b14-wind-chimes span:nth-child(3) { height: 82%; animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b14-wind-chimes span:nth-child(4) { height: 54%; animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b14-wind-chimes span:nth-child(5) { height: 68%; animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b14-wind-chimes::after { content: ''; position: absolute; top: 40%; left: calc(50% - var(--loader-size, 112px) * .065); width: calc(var(--loader-size, 112px) * .13); height: calc(var(--loader-size, 112px) * .13); border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 30%, var(--accent-2)), color-mix(in srgb, #000 20%, var(--accent-2))); animation: darma-loader-darma-b14-wind-chimes-striker calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-wind-chimes-chime { 0%, 100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }
@keyframes darma-loader-darma-b14-wind-chimes-striker { 0%, 100% { transform: translateX(-160%); } 50% { transform: translateX(160%); } }

